from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler
from pathlib import Path
import json
ROOT=Path('/home/runner/work/PlayGround/PlayGround')
HARNESS=Path('/tmp/opencode/roleplay_harness.html')
REQUESTS=[]
class Handler(SimpleHTTPRequestHandler):
    def __init__(self,*args,**kwargs): super().__init__(*args,directory=str(ROOT),**kwargs)
    def do_GET(self):
        if self.path=='/__harness':
            body=HARNESS.read_bytes(); self.send_response(200); self.send_header('Content-Type','text/html'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body); return
        if self.path=='/v1/models':
            body=json.dumps({'data':[{'id':'mock-model'}]}).encode(); self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Access-Control-Allow-Origin','*'); self.end_headers(); self.wfile.write(body); return
        super().do_GET()
    def do_OPTIONS(self):
        self.send_response(204); self.send_header('Access-Control-Allow-Origin','*'); self.send_header('Access-Control-Allow-Headers','Content-Type, Authorization'); self.send_header('Access-Control-Allow-Methods','POST, OPTIONS'); self.end_headers()
    def do_POST(self):
        size=int(self.headers.get('Content-Length','0')); data=json.loads(self.rfile.read(size)); REQUESTS.append(data)
        last=data['messages'][-1]['content']
        if last=='trigger-error': status=503; result={'error':'simulated unavailable'}
        else: status=200; result={'choices':[{'message':{'role':'assistant','content':'Mock reply to: '+last[:100]}}]}
        body=json.dumps(result).encode(); self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Access-Control-Allow-Origin','*'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
    def log_message(self,*args): pass
ThreadingHTTPServer(('127.0.0.1',8765),Handler).serve_forever()

