async (page) => {
  await page.route('**/chat/completions', async route => {
    const body = route.request().postDataJSON();
    const user = body.messages?.[0]?.content;
    const images = Array.isArray(user) ? user.filter(p => p.type === 'image_url').length : 0;
    const times = Array.isArray(user) ? user.filter(p => p.type === 'text' && p.text.startsWith('Frame ')).length : 0;
    await route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ choices: [{ message: { content: 'Mock vision: ' + images + ' sampled images, ' + times + ' timestamp labels. Subject moves left to right.' } }] }) });
  });
  const generated = await page.evaluate(async () => {
    document.querySelector('#openSettings').click();
    document.querySelector('.engine-option[data-mode=server]').click();
    document.querySelector('#apiUrl').value = 'http://vision-mock.test/v1';
    document.querySelector('#modelName').value = 'mock-vision';
    document.querySelector('#saveSettings').click();
    document.querySelector('[data-view=create]').click();
    const canvas = document.createElement('canvas'); canvas.width = 160; canvas.height = 90;
    const ctx = canvas.getContext('2d'); const stream = canvas.captureStream(5); const chunks = [];
    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
    recorder.ondataavailable = e => { if (e.data.size) chunks.push(e.data); };
    recorder.start();
    for (let i = 0; i < 5; i++) { ctx.fillStyle = ['red', 'green', 'blue', 'orange', 'purple'][i]; ctx.fillRect(0, 0, 160, 90); await new Promise(r => setTimeout(r, 200)); }
    await new Promise(resolve => { recorder.onstop = resolve; recorder.stop(); });
    stream.getTracks().forEach(t => t.stop());
    const file = new File(chunks, 'motion-test.webm', { type: 'video/webm' });
    const dt = new DataTransfer(); dt.items.add(file);
    const input = document.querySelector('#videoInput'); input.files = dt.files; input.dispatchEvent(new Event('change', { bubbles: true }));
    return { fileSize: file.size, type: file.type, buttonDisabled: document.querySelector('#analyzeVideo').disabled, status: document.querySelector('#videoStatus').textContent };
  });
  await page.locator('#analyzeVideo').click();
  await page.waitForFunction(() => document.querySelector('#videoAnalysis')?.textContent.includes('Mock vision'), null, { timeout: 30000 });
  return { generated, status: await page.locator('#videoStatus').textContent(), analysis: await page.locator('#videoAnalysis').textContent() };
}

